test('native profile image issuance holds the current owner row until the protected grant finishes',{skip:!process.env.TEST_DATABASE_URL},async()=>{
 const f=await fixture();try{const person=f.actors.staff.person,item=await f.file({person}),p=await profile(f,item,person);await f.serving();const runtime=f.pg.runtime!,connect=runtime.connect.bind(runtime);let release!:()=>void,reached!:()=>void;const gate=new Promise<void>(r=>{release=r;}),atOwner=new Promise<void>(r=>{reached=r;});let paused=false;
 runtime.connect=async()=>{const c=await connect();return {async query<Row=Record<string,unknown>>(sql:string,args?:unknown[]){const r=await c.query<Row>(sql,args);if(!paused&&sql==='SELECT public.community_profile_owner($1,$2,$3) owner'&&args?.[2]===true){paused=true;reached();await gate;}return r;},release(destroy?:boolean){c.release(destroy);}};};let request:ReturnType<typeof profileDownload>|undefined;
 try{request=profileDownload(f,p.id);await Promise.race([atOwner,request.then(()=>{throw new Error('Image issuance ended before current owner lock');})]);await f.pg.exec('BEGIN');try{await assert.rejects(f.pg.query('SELECT id FROM public.people WHERE id=$1 FOR UPDATE NOWAIT',[person]),(e:unknown)=>(e as {code:string}).code==='55P03');}finally{await f.pg.exec('ROLLBACK');}release();assert.equal((await request).response.status,201);await f.pg.exec('BEGIN');try{assert.equal((await f.pg.query('SELECT id FROM public.people WHERE id=$1 FOR UPDATE NOWAIT',[person])).rows.length,1);}finally{await f.pg.exec('ROLLBACK');}}finally{release();await request;runtime.connect=connect;}
 }finally{await f.pg.close();}
});
