check('recorded old inspection/copy evidence does not become an automatic media expiry or require a new upload',async f=>{
 const item=await f.file();await f.serving();
 // Trusted test-owner clock ageing,not a runtime mutation API. Keep the exact
 // observation/attempt chronology and canonical copy fingerprint consistent.
 await f.pg.exec("BEGIN;SET LOCAL TimeZone='UTC'");try{
  await f.pg.query("UPDATE public.file_inspection_attempts SET started_at=started_at-interval '72 hours',finished_at=finished_at-interval '72 hours' WHERE inspection_id=$1",[item.input.inspectionId]);
  await f.pg.query(`UPDATE public.file_scanner_observations SET recorded_at=recorded_at-interval '72 hours',result=result||jsonb_build_object('databaseCreatedAt',to_char(((result->>'databaseCreatedAt')::timestamptz AT TIME ZONE 'UTC')-interval '72 hours','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'observedAt',to_char(((result->>'observedAt')::timestamptz AT TIME ZONE 'UTC')-interval '72 hours','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'observedBeforeAt',to_char(((result->>'observedBeforeAt')::timestamptz AT TIME ZONE 'UTC')-interval '72 hours','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) WHERE inspection_id=$1`,[item.input.inspectionId]);
  await f.pg.query("UPDATE public.file_copy_requests SET source=jsonb_set(source,'{scannerRecordedAt}',to_jsonb((source->>'scannerRecordedAt')::timestamptz-interval '72 hours')),source_fingerprint=encode(sha256(convert_to(jsonb_set(source,'{scannerRecordedAt}',to_jsonb((source->>'scannerRecordedAt')::timestamptz-interval '72 hours'))::text,'UTF8')),'hex'),requested_at=requested_at-interval '72 hours' WHERE id=$1",[item.copyId]);
  await f.pg.query("UPDATE public.file_copy_attempts a SET source_fingerprint=c.source_fingerprint,started_at=a.started_at-interval '72 hours',finished_at=a.finished_at-interval '72 hours' FROM public.file_copy_requests c WHERE c.academy_id=a.academy_id AND c.id=a.copy_id AND c.id=$1",[item.copyId]);await f.pg.exec('COMMIT');
 }catch(error){await f.pg.exec('ROLLBACK');throw error;}
 assert.equal((await f.download(item)).response.status,201);assert.equal((await f.pg.query('SELECT * FROM public.file_records WHERE id=$1',[item.id])).rows.length,1);
});
